#pragma once// Структура заголовка файла сообщений операторуstruct CModel2OperatorMessagesHeader{  DWORD dwName;   //Изменения имени MAP-файла  DWORD dwCount;   DWORD dwReserved[14];};// Размер структуры д.б. кратен степени 2struct CModel2OperatorMessages{  CModel2OperatorMessages()  {    memset( this, 0, sizeof( *this ) );    clrBkg = 0x0000ff;//красный    clrTxt = 0x00ffff;//ж¸лтый  }  int nTime;//Время в секундах от старта модели  int nFlag;//Всяко-разно  BYTE btKvit;// 1-квитировано 0-не квитировано  BYTE btReserved[3];  COLORREF clrBkg;  COLORREF clrTxt;  char szText[108+128];// Текст сообщения + Дополнительная строка сообщения};